// Block (composition) — an inline search form assembled from search Components.
// Arranges only; composes Form/SearchField/Button/Stack.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { SearchField } from "../components/SearchField";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./SearchBar.css";

export interface SearchBarProps {
  /** Hint shown in the search input. */
  placeholder?: string;
  /** Accessible label for the search field. */
  label?: string;
  /** Called with the entered query on submit. */
  onSubmit?: (query: string) => void;
  /** Text shown in the submit button. */
  buttonLabel?: string;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function SearchBar({
  placeholder,
  label = "Search",
  onSubmit,
  buttonLabel = "Search",
  className,
  ref,
}: SearchBarProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.(String(data.get("q") ?? ""));
  };

  return (
    <Form
      ref={ref}
      role="search"
      onSubmit={handleSubmit}
      className={className ? `sd-searchbar ${className}` : "sd-searchbar"}
    >
      <Stack direction="row" gap="small" align="end" className="sd-searchbar__row">
        <SearchField
          className="sd-searchbar__field"
          label={label}
          name="q"
          placeholder={placeholder}
        />
        <Button type="submit" variant="primary">
          {buttonLabel}
        </Button>
      </Stack>
    </Form>
  );
}

/* SearchBar.css — full-width inline arrangement only. */
.sd-searchbar {
  width: 100%;
}

.sd-searchbar__field {
  flex: 1;
  min-width: 0;
}
